<script setup lang="ts">
import {ref,computed,watch} from 'vue';import {artworks,getArt,type Product} from '../data/catalog';import {getSpecOptions} from '../data/editorial';import {commerce,cartCount,toggleFavorite,addToCart,prepareCheckout,openCart,type Selection} from '../stores/commerce';import LineIcon from './LineIcon.vue';import ProductVisual from './ProductVisual.vue';
const props=defineProps<{product:Product;initialArt?:number}>();const opened=ref(false),art=ref(1),spec=ref(''),quantity=ref(1);const favorite=computed(()=>commerce.favorites.includes(props.product.id));
watch(()=>[props.product.id,props.initialArt],()=>{art.value=props.initialArt&&props.initialArt>=1&&props.initialArt<=8?props.initialArt:props.product.art;spec.value=getSpecOptions(props.product)[0];quantity.value=1},{immediate:true});
const selection=():Selection=>({productId:props.product.id,artId:art.value,spec:spec.value,quantity:quantity.value});
function add(){addToCart(selection());opened.value=false;uni.showToast({title:'已加入购物车',icon:'success'})}
function buy(){opened.value=false;prepareCheckout([selection()])}
</script>
<template><view class="purchase-bar"><button role="button" class="purchase-icon" @click="toggleFavorite(product.id)" :aria-label="favorite?'取消收藏':'收藏商品'"><LineIcon name="heart" :size="22" :color="favorite?'#d76171':'#126fa4'"/><text>{{favorite?'已收藏':'收藏'}}</text></button><button role="button" class="purchase-icon" @click="openCart" aria-label="购物车"><view class="cart-icon"><LineIcon name="cart" :size="24"/><text v-if="cartCount" class="badge">{{cartCount>99?'99+':cartCount}}</text></view><text>购物车</text></button><button role="button" class="primary-button purchase-main" @click="opened=true">选择作品与规格</button></view>
<view v-if="opened" class="sheet-mask" @click="opened=false"><view class="selection-sheet" role="dialog" aria-label="选择联名作品与规格" @click.stop><view class="sheet-heading"><text>把喜欢的画，带回日常。</text><button role="button" class="icon-button" @click="opened=false" aria-label="关闭选择"><LineIcon name="close" :size="22"/></button></view><scroll-view scroll-y class="sheet-scroll"><view class="sheet-content"><view class="selection-summary"><view class="selection-thumb"><ProductVisual :product="{...product,art}"/></view><view><text class="summary-title">{{product.name}}</text><text class="summary-sub">售价待公布</text><text class="summary-sub">已选《{{getArt(art).name}}》</text></view></view><text class="field-label">联名作品 <text>8 款</text></text><view class="art-options"><button role="button" v-for="a in artworks" :key="a.id" class="art-option" :class="{chosen:art===a.id}" @click="art=a.id" :aria-label="`选择${a.name}`" :aria-pressed="art===a.id"><image :src="a.image" mode="aspectFill"/><text>{{a.name}}</text><view v-if="art===a.id" class="selected-mark">✓</view></button></view><text class="field-label">{{product.category==='clothing'?'尺码':'产品规格'}}</text><view class="spec-options"><button role="button" v-for="s in getSpecOptions(product)" :key="s" :class="{chosen:spec===s}" @click="spec=s" :aria-pressed="spec===s">{{s}}</button></view><view class="quantity-row"><text class="field-label">数量</text><view class="stepper"><button role="button" @click="quantity=Math.max(1,quantity-1)" :disabled="quantity===1" aria-label="减少数量">−</button><text aria-live="polite">{{quantity}}</text><button role="button" @click="quantity=Math.min(99,quantity+1)" :disabled="quantity===99" aria-label="增加数量">＋</button></view></view><text class="muted-note">作品为 AI 占位图，规格用于交互演示。正式作品、规格及售价待确认。</text></view></scroll-view><view class="sheet-actions"><button role="button" class="secondary-button" @click="add">加入购物车</button><button role="button" class="primary-button" @click="buy">立即选购</button></view></view></view></template>
<style scoped>
