econdary);font-weight:600;display:block;margin-bottom:12px}.field-label text{font-weight:400;color:var(--color-muted);padding-left:8px}.art-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 8px;margin-bottom:24px}.art-option{width:100%;position:relative;padding:4px;border:1px solid var(--color-line);border-radius:10px;background:#fff;text-align:center;min-height:44px}.art-option image{width:100%;height:auto;aspect-ratio:1;border-radius:6px}.art-option>text{font-size:var(--font-caption);line-height:1.4;display:block;margin-top:6px}.chosen{border-color:var(--color-accent)!important;background:var(--color-soft)!important;color:var(--color-accent)}.selected-mark{position:absolute;right:3px;top:3px;background:var(--color-accent);color:#fff;font-size:12px;width:20px;height:20px;border-radius:50%}.spec-options{display:flex;flex-wrap:wrap;gap:8px}.spec-options button{border:1px solid var(--color-line);border-radius:10px;padding:12px;font-size:var(--font-footnote);background:#fff;min-height:44px}.quantity-row{display:flex;align-items:center;justify-content:space-between;margin:24px 0}.quantity-row .field-label{margin:0}.sheet-actions>button{width:100%}.sheet-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:14px 20px calc(14px + var(--safe-bottom,env(safe-area-inset-bottom)));border-top:1px solid var(--color-line);flex:none}
